import csv
import io
import re


def parse_csv(raw_csv: str):
    lines = raw_csv.splitlines(keepends=True)
    header_index = None

    for index, line in enumerate(lines):
        if re.match(r"^\ufeff?\s*Line\s+Number\s*,", line, re.IGNORECASE):
            header_index = index
            break

    if header_index is not None:
        content = "".join(lines[header_index:])
    else:
        content = raw_csv

    reader = csv.reader(io.StringIO(content, newline=""), delimiter=",", quotechar='"', strict=False)
    parsed = list(reader)

    header_position = None
    for index, row in enumerate(parsed):
        if row and re.fullmatch(r"\ufeff?\s*Line\s+Number\s*", row[0], re.IGNORECASE):
            header_position = index
            break

    if header_position is None:
        nonempty = next((i for i, row in enumerate(parsed) if any(cell.strip() for cell in row)), None)
        if nonempty is None:
            return {"columns": [], "rows": []}
        header_position = nonempty

    columns = parsed[header_position]
    rows = []
    width = len(columns)

    for row in parsed[header_position + 1:]:
        if not any(cell.strip() for cell in row):
            continue
        if len(row) < width:
            row = row + [""] * (width - len(row))
        elif len(row) > width and width:
            row = row[:width - 1] + [",".join(row[width - 1:])]
        rows.append(row)

    return {"columns": columns, "rows": rows}
